top -b -n1 -o %CPU 2>/dev/null | head -25 || top -b -n1 | head -25; echo ---; ps -eo pid,pcpu,rss,etime,args --sort=-pcpu | head -15 | cut -c1-200; echo ---; ls -la /var/opt/bmw-voice/state /run/bmw-voice 2>&1 | head -30; echo ---; for f in /run/bmw-voice/*.log /var/opt/bmw-voice/state/*.log; do [ -f "$f" ] && { echo "== $f"; tail -n 60 "$f" | cut -c1-240; }; done; cat /run/bmw-voice/status.json 2>/dev/null | head -c 3000
